const input = $input.first().json;
const body = input.body ?? input;
const expectedLocationId = 'ZzRtp9n8n76ARy99VzJc';
const expectedWebhookKey = 'fnkSDnX3wJ4TwEi4452RWrmal5MByJwH';

function clean(value) {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  return text.length ? text : null;
}

const suppliedKey =
  clean(input.query?.key) ??
  clean(body.webhook_key);

if (suppliedKey !== expectedWebhookKey) {
  throw new Error('Webhook key inválida.');
}

const opportunityId =
  clean(body.opportunity_id) ??
  clean(body.opportunityId);

if (!opportunityId) {
  throw new Error(
    'El payload no contiene opportunity_id. No se acepta body.id como fallback porque puede ser el Contact ID.'
  );
}

const locationId =
  clean(body.location_id) ??
  clean(body.locationId) ??
  expectedLocationId;

if (locationId !== expectedLocationId) {
  throw new Error(
    `Location ID no autorizada: ${locationId}`
  );
}

return [{
  json: {
    event_type:
      clean(body.event_type) ??
      'opportunity_changed',
    received_at: new Date().toISOString(),
    location_id: locationId,
    opportunity_id: opportunityId,
    contact_id:
      clean(body.contact_id) ??
      clean(body.contactId),
    contact_name:
      clean(body.contact_name) ??
      clean(body.contactName),
    contact_email:
      clean(body.contact_email) ??
      clean(body.contactEmail),
    contact_phone:
      clean(body.contact_phone) ??
      clean(body.contactPhone),
    raw_webhook: input
  }
}];

const validated = $('Validate | Secure Payload').first().json;
const opportunityResponse = $('GHL | Get Opportunity').first().json;
const pipelinesResponse = $('GHL | Resolve Pipeline Stage').first().json;

const opportunity =
  opportunityResponse.opportunity ??
  opportunityResponse.data?.opportunity ??
  opportunityResponse.data ??
  opportunityResponse;

const pipelines =
  pipelinesResponse.pipelines ??
  pipelinesResponse.data?.pipelines ??
  [];

function clean(value) {
  if (value === null || value === undefined) return null;

  if (typeof value === 'object') {
    const objectId =
      value.id ??
      value._id ??
      value.userId ??
      value.value;

    if (objectId !== null && objectId !== undefined) {
      const text = String(objectId).trim();
      return text.length ? text : null;
    }

    return null;
  }

  const text = String(value).trim();
  return text.length ? text : null;
}

function toIso(value) {
  if (value === null || value === undefined || value === '') return null;

  let normalized = value;
  if (typeof normalized === 'number' && normalized < 100000000000) {
    normalized *= 1000;
  }

  const date = new Date(normalized);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

const opportunityId =
  clean(opportunity.id) ??
  validated.opportunity_id;

if (opportunityId !== validated.opportunity_id) {
  throw new Error(
    `La API devolvió una opportunity distinta: ${opportunityId}`
  );
}

const pipelineId =
  clean(opportunity.pipelineId) ??
  clean(opportunity.pipeline_id);

const pipelineStageId =
  clean(opportunity.pipelineStageId) ??
  clean(opportunity.pipeline_stage_id) ??
  clean(opportunity.stageId);

let selectedPipeline =
  pipelines.find((pipeline) => clean(pipeline.id) === pipelineId) ??
  pipelines.find((pipeline) =>
    (pipeline.stages ?? []).some(
      (stage) => clean(stage.id) === pipelineStageId
    )
  ) ??
  null;

const selectedStage =
  selectedPipeline?.stages?.find(
    (stage) => clean(stage.id) === pipelineStageId
  ) ??
  null;

const contact =
  opportunity.contact &&
  typeof opportunity.contact === 'object'
    ? opportunity.contact
    : {};

const contactId =
  clean(opportunity.contactId) ??
  clean(opportunity.contact_id) ??
  clean(contact.id) ??
  validated.contact_id;

const assignedUserId =
  clean(opportunity.assignedTo) ??
  clean(opportunity.assignedToId) ??
  clean(opportunity.assignedUserId) ??
  clean(opportunity.userId);

const createdAt = toIso(
  opportunity.dateAdded ??
  opportunity.createdAt ??
  opportunity.created_at
);

const updatedAt = toIso(
  opportunity.dateUpdated ??
  opportunity.updatedAt ??
  opportunity.updated_at ??
  opportunity.lastStatusChangeAt ??
  createdAt
);

const pipelineUpdatedAt = toIso(
  opportunity.lastStageChangeAt ??
  opportunity.pipelineStageChangedAt ??
  opportunity.stageChangedAt ??
  updatedAt
);

const contactName =
  clean(contact.name) ??
  clean(opportunity.contactName) ??
  clean(
    [contact.firstName, contact.lastName]
      .filter(Boolean)
      .join(' ')
  ) ??
  validated.contact_name;

const phone =
  clean(contact.phone) ??
  clean(opportunity.phone) ??
  clean(opportunity.contactPhone) ??
  validated.contact_phone;

const email =
  clean(contact.email) ??
  clean(opportunity.email) ??
  clean(opportunity.contactEmail) ??
  validated.contact_email;

const status = clean(opportunity.status);
const source =
  clean(opportunity.source) ??
  clean(contact.source);

const fingerprintParts = [
  opportunityId,
  pipelineId ?? '',
  updatedAt ?? pipelineUpdatedAt ?? validated.received_at,
  pipelineStageId ?? '',
  status ?? '',
  assignedUserId ?? ''
];

const eventFingerprint = fingerprintParts.join('|');

const compactOpportunityPayload = {
  id: opportunityId,
  contactId,
  pipelineId,
  pipelineStageId,
  stageName: clean(selectedStage?.name),
  status,
  assignedTo: assignedUserId,
  name:
    clean(opportunity.name) ??
    clean(opportunity.opportunityName),
  source,
  dateAdded: createdAt,
  dateUpdated: updatedAt,
  lastStageChangeAt: pipelineUpdatedAt,
  customFields:
    opportunity.customFields ??
    opportunity.custom_fields ??
    null
};

return [{
  json: {
    event_fingerprint: eventFingerprint,
    rpc_body: {
      p_event_fingerprint: eventFingerprint,
      p_event_type: validated.event_type,
      p_received_at: validated.received_at,
      p_location_id: validated.location_id,
      p_opportunity_id: opportunityId,
      p_contact_id: contactId,
      p_pipeline_id: pipelineId,
      p_pipeline_name: clean(selectedPipeline?.name),
      p_pipeline_stage_id: pipelineStageId,
      p_stage_name: clean(selectedStage?.name),
      p_status: status,
      p_assigned_user_id: assignedUserId,
      p_opportunity_name:
        clean(opportunity.name) ??
        clean(opportunity.opportunityName),
      p_contact_name: contactName,
      p_phone: phone,
      p_email: email,
      p_source: source,
      p_created_at: createdAt,
      p_updated_at: updatedAt,
      p_pipeline_updated_at: pipelineUpdatedAt,
      p_raw_payload: {
        webhook: validated.raw_webhook,
        opportunity: compactOpportunityPayload
      }
    }
  }
}];

const response = $input.first().json;
const normalized = $('Normalize | Opportunity Event').first().json;
const result = response?.data !== undefined ? response.data : response;

return [{
  json: {
    ok: true,
    workflow: 'MILHANO | 02 | Opportunity Live Sync V2 | Dual Pipeline',
    pipeline_id: normalized.rpc_body?.p_pipeline_id ?? null,
    pipeline_name: normalized.rpc_body?.p_pipeline_name ?? null,
    stage_name: normalized.rpc_body?.p_stage_name ?? null,
    live_sync: result,
    processed_at: new Date().toISOString()
  }
}];
